mapper.select:
WITH customer_base AS ( SELECT pc.id AS customer_id, '01' AS customer_type_code, pc.name AS customer_name, pc.gender, pc.birth_date, pc.consult_status_code FROM potential_customer pc WHERE pc.conversion_status_code = '01' AND pc.sales_user_id = #{currentUserId}
UNION ALL
SELECT ic.integrated_customer_id AS customer_id, '02' AS customer_type_code, ic.name AS customer_name, ic.gender, ic.birth_date, NULL AS consult_status_code FROM integrated_customer ic WHERE ic.sales_user_id = #{currentUserId} ) SELECT COUNT(*) FROM customer_base cb WHERE 1 = 1
AND LOWER(cb.customer_name) LIKE CONCAT('%', LOWER(#{request.customerName}), '%')
AND TIMESTAMPDIFF(YEAR, cb.birth_date, CURDATE()) = #{request.age}
AND cb.gender = #{request.gender}
AND cb.customer_type_code = #{request.customerStageCode}
AND cb.customer_type_code = '01' AND cb.consult_status_code IN
#{code}
AND cb.customer_type_code = '02' AND ( SELECT c.contract_status_code FROM contract c WHERE c.integrated_customer_id = cb.customer_id ORDER BY CASE c.contract_result_status_code WHEN '01' THEN 1 WHEN '02' THEN 2 WHEN '03' THEN 3 ELSE 9 END, c.updated_at DESC, c.id DESC LIMIT 1 ) IN
#{code}
AND ( CASE WHEN cb.customer_type_code = '01' THEN cb.consult_status_code WHEN cb.customer_type_code = '02' THEN ( SELECT c.contract_status_code FROM contract c WHERE c.integrated_customer_id = cb.customer_id ORDER BY CASE c.contract_result_status_code WHEN '01' THEN 1 WHEN '02' THEN 2 WHEN '03' THEN 3 ELSE 9 END, c.updated_at DESC, c.id DESC LIMIT 1 ) END ) IN
#{code}
AND EXISTS ( SELECT 1 FROM customer_report cr WHERE cr.conversion_status_code = cb.customer_type_code AND cr.customer_id = cb.customer_id )
AND NOT EXISTS ( SELECT 1 FROM customer_report cr WHERE cr.conversion_status_code = cb.customer_type_code AND cr.customer_id = cb.customer_id )
AND EXISTS ( SELECT 1 FROM daily_action_item dai WHERE dai.conversion_status_code = cb.customer_type_code AND dai.customer_id = cb.customer_id AND dai.is_completed = FALSE AND dai.trigger_type_code IN ('06', '07', '08') )
AND NOT EXISTS ( SELECT 1 FROM daily_action_item dai WHERE dai.conversion_status_code = cb.customer_type_code AND dai.customer_id = cb.customer_id AND dai.is_completed = FALSE AND dai.trigger_type_code IN ('06', '07', '08') )
